def align_labels(word_ids, word_labels, label2id, label_all=False, ignore=-100):
    out, prev = [], None
    for w in word_ids:
        if w is None:
            out.append(ignore)
        elif w != prev:
            out.append(label2id[word_labels[w]])          # first piece carries the word's label
        elif label_all:
            lab = word_labels[w]
            if lab.startswith("B-"):
                lab = "I-" + lab[2:]                       # continuation of an entity that already began
            out.append(label2id[lab])
        else:
            out.append(ignore)
        prev = w
    return out
